document.documentElement.style.zoom = '2'; 
for (let i = 0; i < 10; i++) {
  if (window.__ensemble.getState().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break;
  b.click();
  await new Promise(r => setTimeout(r, 900));
}
return 'onboarded=' + window.__ensemble.getState().settings.onboarded + ' size=' + innerWidth + 'x' + innerHeight + ' dpr=' + devicePixelRatio;

const s = window.__ensemble.getState();
const ren = { 'Claude 3': 'Nova', 'Hello': 'Juno', 'ChatGPT': 'Atlas' };
for (const a of s.accounts) if (ren[a.name]) await window.ensemble.updateAccount(a.id, { name: ren[a.name] });
await window.ensemble.updateSettings({ sidebarCollapsed: true, inspector: false });
await new Promise(r => setTimeout(r, 300));
return window.__ensemble.getState().accounts.map(a => a.name).join(', ');

window.__R = 0.03;
const keep = () => { if (document.documentElement.dataset.away !== 'false') document.documentElement.dataset.away = 'false'; };
new MutationObserver(keep).observe(document.documentElement, { attributes: true, attributeFilter: ['data-away'] }); keep();
setInterval(() => { for (const a of document.getAnimations()) if (a.playbackRate !== window.__R) a.playbackRate = window.__R; }, 10);
return 'slowed to ' + window.__R;

window.__S = () => window.__ensemble.getState();
window.__sleep = (ms) => new Promise(r => setTimeout(r, ms));
window.__scroller = () => document.querySelector('[data-view-scope]')?.parentElement;
window.__info = () => { const s = window.__S(); const c = s.chats.find(c => c.id === s.chatId); if (!c) return 'no chat'; const ag = c.agents || []; const t = s.tasks[c.id] || []; const busy = Object.values(s.agents).filter(a => a.chatId === c.id && a.phase !== 'idle' && a.phase !== 'error').length; return 'ag ' + ag.length + ' gone ' + ag.filter(a => a.spawned?.gone).length + ' tasks ' + t.filter(x => x.status === 'done').length + '/' + t.length + ' busy ' + busy + ' neurons ' + document.querySelectorAll('.nn-node').length; };
return 'helpers';

const st = window.__ensemble; const api = window.ensemble;
const chat = await api.createChat({});
await st.getState().openChat(chat.id);
await api.setUltra(chat.id, true);
await api.updateChat(chat.id, { title: 'Design the landing page' });
localStorage.setItem('ensemble.flow.feed', '0');
st.getState().setView('flow');
await new Promise(r => setTimeout(r, 800));
return document.querySelectorAll('.nn-node').length + ' neurons before start, view ' + st.getState().view;
